INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5a0d29ea-cd8b-554c-88e0-51d62eb0f89d', 'Hong Kong Continous Professional Training', 'Guidelines for Continous Professional Training', 'The Guidelines on Continuous Professional Training (Guidelines) are published under section 399 of the Securities and Futures Ordinance,  Cap. 571 (SFO) by the Securities and Futures Commission (SFC). They provide general guidance for persons to comply with the CPT requirements.', 'The Guidelines on Continuous Professional Training (Guidelines) are published under section 399 of the Securities and Futures Ordinance,  Cap. 571 (SFO) by the Securities and Futures Commission (SFC). They provide general guidance for persons to comply with the CPT requirements.', 'The Guidelines on Continuous Professional Training (Guidelines) are published under section 399 of the Securities and Futures Ordinance,  Cap. 571 (SFO) by the Securities and Futures Commission (SFC). They provide general guidance for persons to comply with the CPT requirements.', 'Hong Kong', 'governance', 'in_force', '2022-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_41', ARRAY['sdg4', 'guidance_frameworks', 'other sustainability policy', 'hong kong', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d0644825-d6e1-5cc0-ae15-b0c760f6cb7f', 'Hong Kong How to prepare an ESG Report: Appendix', 'How to prepare an ESG Report: Appendix 2: Reporting Guidance on Environmental KPIs', 'This appendix contains practical guidance on how to collect, calculate and report the information called for under each of the KPIs in Part C “Subject Area A. Environmental” of the ESG Guide. This guidance is for general reference only. Depending on the issuer’s industry and geographical location(s) of its operations, it may refer to other resources. Furthermore, when compiling data for these KPIs, the issuer should consider its own circumstances to determine the depth and breadth of disclosure that is material and appropriate for its business.', 'This appendix contains practical guidance on how to collect, calculate and report the information called for under each of the KPIs in Part C “Subject Area A. Environmental” of the ESG Guide. This guidance is for general reference only. Depending on the issuer’s industry and geographical location(s) of its operations, it may refer to other resources. Furthermore, when compiling data for these KPIs, the issuer should consider its own circumstances to determine the depth and breadth of disclosure that is material and appropriate for its business.', 'This appendix contains practical guidance on how to collect, calculate and report the information called for under each of the KPIs in Part C “Subject Area A. Environmental” of the ESG Guide. This guidance is for general reference only. Depending on the issuer’s industry and geographical location(s) of its operations, it may refer to other resources. Furthermore, when compiling data for these KPIs, the issuer should consider its own circumstances to determine the depth and breadth of disclosure that is material and appropriate for its business.', 'Hong Kong', 'climate', 'in_force', '2022-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_63', ARRAY['guidance_frameworks', 'hong kong', 'sdg7', 'sdg11', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3dab6877-6893-519d-b08d-1f5a25d28552', 'Hong Kong Due Diligence Processes for Green and Sustainable', 'Due Diligence Processes for Green and Sustainable Products, 2022', 'The Hong Kong Monetary Authority (HKMA) has recently undertaken a round of thematic examinations focused on the development and ongoing management of green and sustainable products. The objective of this Guide is to ensure that the authorized institutions (AIs) examined have put in place proper systems of control to ensure that these products and the related funds are managed in a way consistent with their climate strategies, thereby reducing any potential exposures to greenwashing risks.', 'The Hong Kong Monetary Authority (HKMA) has recently undertaken a round of thematic examinations focused on the development and ongoing management of green and sustainable products. The objective of this Guide is to ensure that the authorized institutions (AIs) examined have put in place proper systems of control to ensure that these products and the related funds are managed in a way consistent with their climate strategies, thereby reducing any potential exposures to greenwashing risks.', 'The Hong Kong Monetary Authority (HKMA) has recently undertaken a round of thematic examinations focused on the development and ongoing management of green and sustainable products. The objective of this Guide is to ensure that the authorized institutions (AIs) examined have put in place proper systems of control to ensure that these products and the related funds are managed in a way consistent with their climate strategies, thereby reducing any potential exposures to greenwashing risks.', 'Hong Kong', 'climate', 'in_force', '2022-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_65', ARRAY['sdg13', 'hong kong', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('79fad15b-cb81-5cd6-882d-1bbde8fc7f6c', 'Hong Kong Embedding climate risk in banking supervision', 'Embedding climate risk in banking supervision 2022', 'Presents Hong Kong Monetary Authority (HKMA)’s two-year plan to integrate climate risk into its banking supervisory processes.', 'Presents Hong Kong Monetary Authority (HKMA)’s two-year plan to integrate climate risk into its banking supervisory processes.', 'Presents Hong Kong Monetary Authority (HKMA)’s two-year plan to integrate climate risk into its banking supervisory processes.', 'Hong Kong', 'climate', 'in_force', '2022-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_67', ARRAY['sdg13', 'hong kong', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d3631ec9-52dd-5a2e-900f-c669c13bf8bf', 'Hong Kong BCBS Principles for the Effective Management and', 'BCBS Principles for the Effective Management and Supervision of Climaterelated Financial Risk 2022', 'Expresses the HKMA’s support for the Principles for the Effective Management and Supervision of Climate-related Financial Risks (“the Principles”) recently issued by the Basel Committee on Banking Supervision (“BCBS”) following public consultation.', 'Expresses the HKMA’s support for the Principles for the Effective Management and Supervision of Climate-related Financial Risks (“the Principles”) recently issued by the Basel Committee on Banking Supervision (“BCBS”) following public consultation.', 'Expresses the HKMA’s support for the Principles for the Effective Management and Supervision of Climate-related Financial Risks (“the Principles”) recently issued by the Basel Committee on Banking Supervision (“BCBS”) following public consultation.', 'Hong Kong', 'climate', 'in_force', '2022-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_68', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'hong kong', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a580f7e1-5103-522f-b5b1-9fb4f5a491c4', 'Hong Kong Embedding climate risk in banking supervision', 'Embedding climate risk in banking supervision', 'Outlines the Hong Kong Monetary Authority (HKMA)’s two-year plan to integrate climate risk into its banking supervisory processes.', 'Outlines the Hong Kong Monetary Authority (HKMA)’s two-year plan to integrate climate risk into its banking supervisory processes.', 'Outlines the Hong Kong Monetary Authority (HKMA)’s two-year plan to integrate climate risk into its banking supervisory processes.', 'Hong Kong', 'climate', 'in_force', '2022-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_70', ARRAY['sdg13', 'hong kong', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f549eb27-5259-5c05-bf6d-ea4f4b8c06c3', 'Hong Kong Beam Plus New Buildings Version 2.0', 'Beam Plus New Buildings Version 2.0', 'The upgraded BEAM Plus New Buildings Version 2.0 (NB v2.0) aims to be practical, clear and standardised in defining the key elements of green buildings including health and wellbeing, hygiene, site impacts, use of materials, water quality, energy efficiency, indoor environmental quality, etc.', 'The upgraded BEAM Plus New Buildings Version 2.0 (NB v2.0) aims to be practical, clear and standardised in defining the key elements of green buildings including health and wellbeing, hygiene, site impacts, use of materials, water quality, energy efficiency, indoor environmental quality, etc.', 'The upgraded BEAM Plus New Buildings Version 2.0 (NB v2.0) aims to be practical, clear and standardised in defining the key elements of green buildings including health and wellbeing, hygiene, site impacts, use of materials, water quality, energy efficiency, indoor environmental quality, etc.', 'Hong Kong', 'climate', 'in_force', '2021-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_21', ARRAY['other sustainability policy', 'hong kong', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'sdg6', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eda49997-a3aa-526e-aec7-f0249a5dbbd6', 'Hong Kong Circular Management companies of SFC-authorized unit trusts', 'Circular Management companies of SFC-authorized unit trusts and mutual funds', 'This circular supersedes the 2019 Circular and sets out the SFC’s expectations with respect to how requirements under the SFC Handbook for Unit Trusts and Mutual Funds, Investment-Linked Assurance Schemes and Unlisted Structured Investment Products (“Handbook”) apply to SFC-authorized funds which consider climate change or green or ESG or sustainability factors (collectively, “ESG factors”) in their investment process.', 'This circular supersedes the 2019 Circular and sets out the SFC’s expectations with respect to how requirements under the SFC Handbook for Unit Trusts and Mutual Funds, Investment-Linked Assurance Schemes and Unlisted Structured Investment Products (“Handbook”) apply to SFC-authorized funds which consider climate change or green or ESG or sustainability factors (collectively, “ESG factors”) in their investment process.', 'This circular supersedes the 2019 Circular and sets out the SFC’s expectations with respect to how requirements under the SFC Handbook for Unit Trusts and Mutual Funds, Investment-Linked Assurance Schemes and Unlisted Structured Investment Products (“Handbook”) apply to SFC-authorized funds which consider climate change or green or ESG or sustainability factors (collectively, “ESG factors”) in their investment process.', 'Hong Kong', 'climate', 'in_force', '2021-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_24', ARRAY['sdg13', 'hong kong', 'regulations', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8bea6bfb-fdc6-5d70-aa45-67f319b1c8ab', 'Hong Kong Summary of Carbon Footprint for Listed Companies', 'Summary of Carbon Footprint for Listed Companies Submission and Declaration of Consent for Disclosure', 'This is the form that companies complete to register their carbon footprint in Hong Kong.', 'This is the form that companies complete to register their carbon footprint in Hong Kong.', 'This is the form that companies complete to register their carbon footprint in Hong Kong.', 'Hong Kong', 'climate', 'in_force', '2021-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_39', ARRAY['sdg13', 'other sustainability policy', 'hong kong', 'sdg7', 'mandatory', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('91add202-a6c0-595a-980c-39b18eebbecf', 'Hong Kong Voluntary Water Efficiency Labelling Scheme (WELS) on', 'Voluntary Water Efficiency Labelling Scheme (WELS) on Showers for Bathing', 'The Voluntary Water Efficiency Labelling Scheme (WELS) on Showers for Bathing in Hong Kong aims to promote water efficiency by labeling showers based on their water usage. The policy requires companies to register their shower models, including their water efficiency grade and nominal flow rate. This voluntary scheme helps consumers make informed choices and encourages companies to develop more water-efficient shower products. The policy is industry-specific and focuses on the water usage of shower and flow controllers.', 'The Voluntary Water Efficiency Labelling Scheme (WELS) on Showers for Bathing in Hong Kong aims to promote water efficiency by labeling showers based on their water usage. The policy requires companies to register their shower models, including their water efficiency grade and nominal flow rate. This voluntary scheme helps consumers make informed choices and encourages companies to develop more water-efficient shower products. The policy is industry-specific and focuses on the water usage of shower and flow controllers.', 'The Voluntary Water Efficiency Labelling Scheme (WELS) on Showers for Bathing in Hong Kong aims to promote water efficiency by labeling showers based on their water usage. The policy requires companies to register their shower models, including their water efficiency grade and nominal flow rate. This voluntary scheme helps consumers make informed choices and encourages companies to develop more water-efficient shower products. The policy is industry-specific and focuses on the water usage of shower and flow controllers.', 'Hong Kong', 'governance', 'in_force', '2021-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_57', ARRAY['other sustainability policy', 'hong kong', 'sdg6', 'voluntary', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4aee1445-6b31-5eee-86f2-af6be706b3a4', 'Hong Kong Review of Corporate Governance Code & Related', 'Review of Corporate Governance Code & Related Listing Rules, and Housekeeping Rule Amendments', 'This paper presents the results of a consultation whereby the Exchange received a total of 214 submissions 1 from a broad range of respondents, including listed companies, professional bodies and industry associations, market practitioners, investment managers, non-governmental organisations and individuals.', 'This paper presents the results of a consultation whereby the Exchange received a total of 214 submissions 1 from a broad range of respondents, including listed companies, professional bodies and industry associations, market practitioners, investment managers, non-governmental organisations and individuals.', 'This paper presents the results of a consultation whereby the Exchange received a total of 214 submissions 1 from a broad range of respondents, including listed companies, professional bodies and industry associations, market practitioners, investment managers, non-governmental organisations and individuals.', 'Hong Kong', 'governance', 'in_force', '2021-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_60', ARRAY['other sustainability policy', 'hong kong', 'regulations', 'mandatory', 'sdg16', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3affc6d8-7f88-5195-84c2-29c03d80ef4d', 'Hong Kong Climate Disclosures', 'Guidance on Climate Disclosures 2021', 'With effect from July 2020, HKEX’s ESG Reporting Guide has been amended to incorporate elements of the TCFD recommendations such as requiring board’s oversight of ESG matters, targets for certain environmental KPIs and disclosure of impact of significant climate-related issues. In light of the direction towards mandatory TCFD-aligned climate-related disclosures by 2025, we encourage our listed issuers to commence reporting in accordance with the TCFD recommendations the soonest. The purpose of the Guidance on Climate Disclosures (the Guide)2 is to provide practical guidance to facilitate listed companies in complying with the TCFD recommendations.3 This Guide is targeted at companies that are yet to develop substantive in-house expertise on climate-related issues, and seeks to mitigate the many challenges currently faced by most companies in TCFD reporting, including: (1) Lack of understanding of concepts relating to climate change issues; (2) Insufficient resources (e.g. lack of access to sustainability experts and lack of data); (3) Unclear roles and responsibilities; (4) Lack of awareness from different corporate departments.', 'With effect from July 2020, HKEX’s ESG Reporting Guide has been amended to incorporate elements of the TCFD recommendations such as requiring board’s oversight of ESG matters, targets for certain environmental KPIs and disclosure of impact of significant climate-related issues. In light of the direction towards mandatory TCFD-aligned climate-related disclosures by 2025, we encourage our listed issuers to commence reporting in accordance with the TCFD recommendations the soonest. The purpose of the Guidance on Climate Disclosures (the Guide)2 is to provide practical guidance to facilitate listed companies in complying with the TCFD recommendations.3 This Guide is targeted at companies that are yet to develop substantive in-house expertise on climate-related issues, and seeks to mitigate the many challenges currently faced by most companies in TCFD reporting, including: (1) Lack of understanding of concepts relating to climate change issues; (2) Insufficient resources (e.g. lack of access to sustainability experts and lack of data); (3) Unclear roles and responsibilities; (4) Lack of awareness from different corporate departments.', 'With effect from July 2020, HKEX’s ESG Reporting Guide has been amended to incorporate elements of the TCFD recommendations such as requiring board’s oversight of ESG matters, targets for certain environmental KPIs and disclosure of impact of significant climate-related issues. In light of the direction towards mandatory TCFD-aligned climate-related disclosures by 2025, we encourage our listed issuers to commence reporting in accordance with the TCFD recommendations the soonest. The purpose of the Guidance on Climate Disclosures (the Guide)2 is to provide practical guidance to facilitate listed companies in complying with the TCFD recommendations.3 This Guide is targeted at companies that are yet to develop substantive in-house expertise on climate-related issues, and seeks to mitigate the many challenges currently faced by most companies in TCFD reporting, including: (1) Lack of understanding of concepts relating to climate change issues; (2) Insufficient resources (e.g. lack of access to sustainability experts and lack of data); (3) Unclear roles and responsibilities; (4) Lack of awareness from different corporate departments.', 'Hong Kong', 'climate', 'in_force', '2021-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_64', ARRAY['guidance_frameworks', 'sdg13', 'hong kong', 'sdg7', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d4cbed2d-c2d1-5599-a850-e4dacf62734e', 'Hong Kong Supervisory Policy Manual Climate Risk Management', 'Supervisory Policy Manual Climate Risk Management, 2021', 'To provide guidance to AIs on the key elements of climate-related risk management; and to set out the HKMA’s approach to, and expectations in, reviewing AIs’ climate-related risk management.', 'To provide guidance to AIs on the key elements of climate-related risk management; and to set out the HKMA’s approach to, and expectations in, reviewing AIs’ climate-related risk management.', 'To provide guidance to AIs on the key elements of climate-related risk management; and to set out the HKMA’s approach to, and expectations in, reviewing AIs’ climate-related risk management.', 'Hong Kong', 'climate', 'in_force', '2021-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_69', ARRAY['sdg13', 'hong kong', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('267944f8-73fb-5418-a569-2c76e9768740', 'Strategic Plan to Strengthen Hong Kong’s Financial Ecosystem', 'Strategic Plan to Strengthen Hong Kong’s Financial Ecosystem to Support a Greener and More Sustainable Future', 'This Strategic Plan sets out how Hong Kong will achieve this goal and consolidate its position as a leading green and sustainable finance and risk management centre, by strengthening the resilience and capabilities of our robust financial system, as well as by promoting market and product development and innovation whilst leveraging international collaboration and alignment to capture the enormous opportunities ahead.', 'This Strategic Plan sets out how Hong Kong will achieve this goal and consolidate its position as a leading green and sustainable finance and risk management centre, by strengthening the resilience and capabilities of our robust financial system, as well as by promoting market and product development and innovation whilst leveraging international collaboration and alignment to capture the enormous opportunities ahead.', 'This Strategic Plan sets out how Hong Kong will achieve this goal and consolidate its position as a leading green and sustainable finance and risk management centre, by strengthening the resilience and capabilities of our robust financial system, as well as by promoting market and product development and innovation whilst leveraging international collaboration and alignment to capture the enormous opportunities ahead.', 'Hong Kong', 'climate', 'in_force', '2020-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_19', ARRAY['sdg13', 'sdg14', 'hong kong', 'other sustainability policy', 'sdg9', 'sdg17', 'mandatory', 'mandatory_regulations', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4a8cebd2-b30f-5431-b2e0-76f39233aff6', 'Hong Kong Consumer Goods Safety Ordinance (Cap 456)', 'Consumer Goods Safety Ordinance (Cap 456)', 'This document outlines an Ordinance to impose a duty on manufacturers, importers and suppliers of certain consumer goods to ensure that the consumer goods they supply are safe and for incidental purposes.', 'This document outlines an Ordinance to impose a duty on manufacturers, importers and suppliers of certain consumer goods to ensure that the consumer goods they supply are safe and for incidental purposes.', 'This document outlines an Ordinance to impose a duty on manufacturers, importers and suppliers of certain consumer goods to ensure that the consumer goods they supply are safe and for incidental purposes.', 'Hong Kong', 'climate', 'in_force', '2020-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_28', ARRAY['other sustainability policy', 'hong kong', 'regulations', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('15af4401-57ad-5e4e-ad19-ad7906a13b24', 'Hong Kong How to Prepare an ESG Report: A', 'How to Prepare an ESG Report: A Step-by-Step Guide to ESG Reporting', 'The ''How to Prepare an ESG Report'' policy by Hong Kong Exchange (HKEX) in 2020 provides a step-by-step guide for ESG reporting, emphasizing the importance of environmental, social, and governance (ESG) disclosures for investor decision-making. It highlights the value of ESG strategies in mitigating financial risks and promoting long-term company sustainability. The policy adopts a ''comply or explain'' approach, requiring issuers to report on material ESG issues or explain why certain information is not disclosed. It aims to enhance transparency, risk management, and sustainable value creation in companies.', 'The ''How to Prepare an ESG Report'' policy by Hong Kong Exchange (HKEX) in 2020 provides a step-by-step guide for ESG reporting, emphasizing the importance of environmental, social, and governance (ESG) disclosures for investor decision-making. It highlights the value of ESG strategies in mitigating financial risks and promoting long-term company sustainability. The policy adopts a ''comply or explain'' approach, requiring issuers to report on material ESG issues or explain why certain information is not disclosed. It aims to enhance transparency, risk management, and sustainable value creation in companies.', 'The ''How to Prepare an ESG Report'' policy by Hong Kong Exchange (HKEX) in 2020 provides a step-by-step guide for ESG reporting, emphasizing the importance of environmental, social, and governance (ESG) disclosures for investor decision-making. It highlights the value of ESG strategies in mitigating financial risks and promoting long-term company sustainability. The policy adopts a ''comply or explain'' approach, requiring issuers to report on material ESG issues or explain why certain information is not disclosed. It aims to enhance transparency, risk management, and sustainable value creation in companies.', 'Hong Kong', 'climate', 'in_force', '2020-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_8', ARRAY['hong kong', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2337a947-e122-5357-98ac-9bff0df6ddd3', 'Hong Kong Circular to management companies of SFC-authorized unit', 'Circular to management companies of SFC-authorized unit trusts and mutual funds - Green or ESG funds', 'This circular applies to SFC-authorized funds with incorporate one or more of the globally recognized green or ESG criteria of principles (set out in Annex 1 to this circular) as their key investment focus and reflects such in their name and investment objective or strategy (Green or ESG funds).', 'This circular applies to SFC-authorized funds with incorporate one or more of the globally recognized green or ESG criteria of principles (set out in Annex 1 to this circular) as their key investment focus and reflects such in their name and investment objective or strategy (Green or ESG funds).', 'This circular applies to SFC-authorized funds with incorporate one or more of the globally recognized green or ESG criteria of principles (set out in Annex 1 to this circular) as their key investment focus and reflects such in their name and investment objective or strategy (Green or ESG funds).', 'Hong Kong', 'climate', 'in_force', '2019-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_16', ARRAY['guidance_frameworks', 'sdg13', 'hong kong', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1ba73458-d776-5d5b-bcca-ab7b4b5f8e8f', 'Hong Kong Common Assessment Framework on Green and Sustainable', 'Common Assessment Framework on Green and Sustainable Banking', 'The Common Assessment Framework on Green and Sustainable Banking in Hong Kong aims to assess institutions'' readiness in addressing climate and environment-related risks. It includes 20 sub-elements grouped under six key elements such as governance, risk management, business policies, and disclosure. Institutions conduct a self-assessment and provide evidence of their responses, focusing on financial risks associated with climate issues. The framework requires completion on a Hong Kong office basis and submission of quantitative information on climate and environmental risks. Institutions are encouraged to elaborate on their risk management approach and stage of development. The policy emphasizes the importance of addressing physical and transition risks in a lower-carbon economy.', 'The Common Assessment Framework on Green and Sustainable Banking in Hong Kong aims to assess institutions'' readiness in addressing climate and environment-related risks. It includes 20 sub-elements grouped under six key elements such as governance, risk management, business policies, and disclosure. Institutions conduct a self-assessment and provide evidence of their responses, focusing on financial risks associated with climate issues. The framework requires completion on a Hong Kong office basis and submission of quantitative information on climate and environmental risks. Institutions are encouraged to elaborate on their risk management approach and stage of development. The policy emphasizes the importance of addressing physical and transition risks in a lower-carbon economy.', 'The Common Assessment Framework on Green and Sustainable Banking in Hong Kong aims to assess institutions'' readiness in addressing climate and environment-related risks. It includes 20 sub-elements grouped under six key elements such as governance, risk management, business policies, and disclosure. Institutions conduct a self-assessment and provide evidence of their responses, focusing on financial risks associated with climate issues. The framework requires completion on a Hong Kong office basis and submission of quantitative information on climate and environmental risks. Institutions are encouraged to elaborate on their risk management approach and stage of development. The policy emphasizes the importance of addressing physical and transition risks in a lower-carbon economy.', 'Hong Kong', 'climate', 'in_force', '2019-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_17', ARRAY['sdg13', 'other sustainability policy', 'hong kong', 'voluntary', 'sdg16', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c686545e-75f1-5d33-9612-195a30912cf1', 'Hong Kong Reviewing the "Guidelines for Environmental, Social and', 'Reviewing the "Guidelines for Environmental, Social and Governance (ESG) Reporting" and related provisions in the "Listing Rules"', 'To increase public concern regarding companies'' ESG performance in addition to financial and operational performance. ESG reporting can help a company to manage the expectations of its stakeholders, including investors, customers, employees and the wider community, with respect to its ESG performance, communicate any strong aspects of this performance and thereby enhance the level of trust in its brand and its reputation.', 'To increase public concern regarding companies'' ESG performance in addition to financial and operational performance. ESG reporting can help a company to manage the expectations of its stakeholders, including investors, customers, employees and the wider community, with respect to its ESG performance, communicate any strong aspects of this performance and thereby enhance the level of trust in its brand and its reputation.', 'To increase public concern regarding companies'' ESG performance in addition to financial and operational performance. ESG reporting can help a company to manage the expectations of its stakeholders, including investors, customers, employees and the wider community, with respect to its ESG performance, communicate any strong aspects of this performance and thereby enhance the level of trust in its brand and its reputation.', 'Hong Kong', 'climate', 'in_force', '2019-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_61', ARRAY['guidance_frameworks', 'hong kong', 'sdg11', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eba213f1-6374-54eb-aa9c-0f878af95062', 'Hong Kong Strategic Framework for Green Finance', 'Strategic Framework for Green Finance', 'In publishing this paper, the SFC aims to discuss what we as a market regulator can do to develop green finance in Hong Kong.', 'In publishing this paper, the SFC aims to discuss what we as a market regulator can do to develop green finance in Hong Kong.', 'In publishing this paper, the SFC aims to discuss what we as a market regulator can do to develop green finance in Hong Kong.', 'Hong Kong', 'climate', 'in_force', '2018-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_18', ARRAY['sdg13', 'voluntary_frameworks', 'hong kong', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bad38c37-cf5d-5ea2-b80e-d91309f33e1b', 'Hong Kong Guidelines of Anti-Money Laundering and Counter-Financing on', 'Guidelines of Anti-Money Laundering and Counter-Financing on Terrorism', 'This Guideline is issued by the Hong Kong Monetary Authority (HKMA) and sets out the relevant anti-money laundering and counter-financing of terrorism (AML/CFT) statutory and regulatory requirements, and the AML/CFT standards which Authorized Institutions (AIs), including Registered Institutions (RIs) 1 , should meet in order to comply with the statutory requirements under the AMLO and the BO. Compliance with this Guideline is enforced through the AMLO and the BO.', 'This Guideline is issued by the Hong Kong Monetary Authority (HKMA) and sets out the relevant anti-money laundering and counter-financing of terrorism (AML/CFT) statutory and regulatory requirements, and the AML/CFT standards which Authorized Institutions (AIs), including Registered Institutions (RIs) 1 , should meet in order to comply with the statutory requirements under the AMLO and the BO. Compliance with this Guideline is enforced through the AMLO and the BO.', 'This Guideline is issued by the Hong Kong Monetary Authority (HKMA) and sets out the relevant anti-money laundering and counter-financing of terrorism (AML/CFT) statutory and regulatory requirements, and the AML/CFT standards which Authorized Institutions (AIs), including Registered Institutions (RIs) 1 , should meet in order to comply with the statutory requirements under the AMLO and the BO. Compliance with this Guideline is enforced through the AMLO and the BO.', 'Hong Kong', 'governance', 'in_force', '2018-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_40', ARRAY['guidance_frameworks', 'voluntary', 'hong kong', 'other sustainability policy']::text[]) ON CONF