INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('41b9fbbe-8bf6-5b81-bd42-a2c6af9e13da', 'Hong Kong brief overview of the Modern Slavery Bill', 'A brief overview of the Modern Slavery Bill 2017', 'This Bill proposes to criminalise the several acts by amending the Crimes Ordinance (Cap. 200).', 'This Bill proposes to criminalise the several acts by amending the Crimes Ordinance (Cap. 200).', 'This Bill proposes to criminalise the several acts by amending the Crimes Ordinance (Cap. 200).', 'Hong Kong', 'climate', 'in_force', '2017-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_14', ARRAY['sdg8', 'other sustainability policy', 'hong kong', 'regulations', 'sdg11', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fd09504f-d1ea-5bcc-ac15-7d8c70f32375', 'Hong Kong Prevention of Bribery Ordinance (Cap 201)', 'Prevention of Bribery Ordinance (Cap 201)', 'This ordinance aims to make further and better provision for the prevention of bribery and for purposes necessary thereto or connected therewith.', 'This ordinance aims to make further and better provision for the prevention of bribery and for purposes necessary thereto or connected therewith.', 'This ordinance aims to make further and better provision for the prevention of bribery and for purposes necessary thereto or connected therewith.', 'Hong Kong', 'governance', 'in_force', '2017-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_56', ARRAY['other sustainability policy', 'hong kong', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
