INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('33b1fbaa-8d40-52ef-b144-c52e9ef15c37', 'Hong Kong Principles of Responsible Ownership', 'Principles of Responsible Ownership', 'The Principles of Responsible Ownership (Principles) are a set of principles and guidance to assist investors to determine how best to meet their ownership responsibilities.', 'The Principles of Responsible Ownership (Principles) are a set of principles and guidance to assist investors to determine how best to meet their ownership responsibilities.', 'The Principles of Responsible Ownership (Principles) are a set of principles and guidance to assist investors to determine how best to meet their ownership responsibilities.', 'Hong Kong', 'governance', 'in_force', '2016-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_7', ARRAY['guidance_frameworks', 'other sustainability policy', 'hong kong', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b64061b3-401e-5a6c-8998-18c580260af7', 'Hong Kong Construction Industry Safety Award Scheme', 'Construction Industry Safety Award Scheme', 'The objectives of the Award Scheme are to raise the safety and health awareness of contractors, site personnel and workers of the construction industry; to foster a positive safety culture and encourage the adoption of safe work practices in the industry; and, through an open competition, to award contractors, site personnel and workers in recognition of their good occupational safety and health performances.', 'The objectives of the Award Scheme are to raise the safety and health awareness of contractors, site personnel and workers of the construction industry; to foster a positive safety culture and encourage the adoption of safe work practices in the industry; and, through an open competition, to award contractors, site personnel and workers in recognition of their good occupational safety and health performances.', 'The objectives of the Award Scheme are to raise the safety and health awareness of contractors, site personnel and workers of the construction industry; to foster a positive safety culture and encourage the adoption of safe work practices in the industry; and, through an open competition, to award contractors, site personnel and workers in recognition of their good occupational safety and health performances.', 'Hong Kong', 'social', 'in_force', '2015-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_27', ARRAY['sdg8', 'other sustainability policy', 'hong kong', 'regulations', 'mandatory', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('08d33c8d-9147-5930-8757-02e822594536', 'Hong Kong Data Breach Handling and the Giving of', 'Guidance on Data Breach Handling and the Giving of Breach Notifications', 'This guidance note aims to assist data users in handling data breaches, and to mitigate the loss and damage caused to the data subjects concerned, particularly when sensitive personal data is involved.', 'This guidance note aims to assist data users in handling data breaches, and to mitigate the loss and damage caused to the data subjects concerned, particularly when sensitive personal data is involved.', 'This guidance note aims to assist data users in handling data breaches, and to mitigate the loss and damage caused to the data subjects concerned, particularly when sensitive personal data is involved.', 'Hong Kong', 'governance', 'in_force', '2015-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_37', ARRAY['guidance_frameworks', 'mandatory', 'other sustainability policy', 'hong kong']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('11d704d1-875b-5254-9455-92a8c7213b4b', 'Hong Kong Water Disposal Ordinance (Cap 354)', 'Water Disposal Ordinance (Cap 354)', 'This ordinance aims to provide for the control and regulation of the production, storage, collection and disposal including the treatment, reprocessing and recycling of waste of any class or description, the licensing and registration of places and persons connected with any such activity, the protection and safety of the public in relation to any such activity and to provide for matters incidental thereto.', 'This ordinance aims to provide for the control and regulation of the production, storage, collection and disposal including the treatment, reprocessing and recycling of waste of any class or description, the licensing and registration of places and persons connected with any such activity, the protection and safety of the public in relation to any such activity and to provide for matters incidental thereto.', 'This ordinance aims to provide for the control and regulation of the production, storage, collection and disposal including the treatment, reprocessing and recycling of waste of any class or description, the licensing and registration of places and persons connected with any such activity, the protection and safety of the public in relation to any such activity and to provide for matters incidental thereto.', 'Hong Kong', 'climate', 'in_force', '2015-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_58', ARRAY['sdg2', 'other sustainability policy', 'hong kong', 'regulations', 'mandatory', 'sdg6', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0cbe0d54-f79c-5991-b6e2-94ea7675e2c1', 'Hong Kong Companies Ordinance (Cap. 622)', 'Companies Ordinance (Cap. 622)', 'The Companies Ordinance (Cap. 622) in Hong Kong, last updated in 2019, regulates company formation, registration, and governance. It covers interpretation, types of companies (limited, unlimited, private, public), holding companies, registration procedures, company names, and articles. The ordinance outlines requirements for incorporation forms, certificates, articles of association, and company names. It aims to ensure transparency, compliance, and proper functioning of companies in Hong Kong.', 'The Companies Ordinance (Cap. 622) in Hong Kong, last updated in 2019, regulates company formation, registration, and governance. It covers interpretation, types of companies (limited, unlimited, private, public), holding companies, registration procedures, company names, and articles. The ordinance outlines requirements for incorporation forms, certificates, articles of association, and company names. It aims to ensure transparency, compliance, and proper functioning of companies in Hong Kong.', 'The Companies Ordinance (Cap. 622) in Hong Kong, last updated in 2019, regulates company formation, registration, and governance. It covers interpretation, types of companies (limited, unlimited, private, public), holding companies, registration procedures, company names, and articles. The ordinance outlines requirements for incorporation forms, certificates, articles of association, and company names. It aims to ensure transparency, compliance, and proper functioning of companies in Hong Kong.', 'Hong Kong', 'governance', 'in_force', '2014-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_3', ARRAY['hong kong', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7013c2a4-f8a7-56eb-9bc1-d59a85f45de9', 'Hong Kong BEC Handbook: Understanding Materiality for Environmental, Social', 'BEC Handbook: Understanding Materiality for Environmental, Social and Governance Reporting', 'The BEC Handbook: Understanding Materiality for Environmental, Social and Governance Reporting 2014 is a guide developed by the Business Environment Council in Hong Kong to assist companies in understanding materiality and how to report on environmental, social, and governance (ESG) issues. The handbook defines materiality as the degree to which an issue is relevant or significant to an organization, taking into account both the impact of the issue and the stakeholder concern or interest in the issue. The handbook provides guidance on how to identify and prioritize ESG issues based on their materiality, and how to report on these issues effectively. The handbook covers several key areas, including the business case for materiality, how to assess materiality, how to determine stakeholder relevance and engagement, and how to report on material ESG issues. The handbook provides case studies and practical examples to illustrate these concepts and guide companies through the reporting process. The aim of the handbook is to help companies in Hong Kong improve their ESG reporting and ensure that their reporting is relevant, meaningful, and transparent to stakeholders. The handbook is designed for companies of all sizes and sectors, and can be used as a reference guide for those looking to improve their ESG reporting practices.', 'The BEC Handbook: Understanding Materiality for Environmental, Social and Governance Reporting 2014 is a guide developed by the Business Environment Council in Hong Kong to assist companies in understanding materiality and how to report on environmental, social, and governance (ESG) issues. The handbook defines materiality as the degree to which an issue is relevant or significant to an organization, taking into account both the impact of the issue and the stakeholder concern or interest in the issue. The handbook provides guidance on how to identify and prioritize ESG issues based on their materiality, and how to report on these issues effectively. The handbook covers several key areas, including the business case for materiality, how to assess materiality, how to determine stakeholder relevance and engagement, and how to report on material ESG issues. The handbook provides case studies and practical examples to illustrate these concepts and guide companies through the reporting process. The aim of the handbook is to help companies in Hong Kong improve their ESG reporting and ensure that their reporting is relevant, meaningful, and transparent to stakeholders. The handbook is designed for companies of all sizes and sectors, and can be used as a reference guide for those looking to improve their ESG reporting practices.', 'The BEC Handbook: Understanding Materiality for Environmental, Social and Governance Reporting 2014 is a guide developed by the Business Environment Council in Hong Kong to assist companies in understanding materiality and how to report on environmental, social, and governance (ESG) issues. The handbook defines materiality as the degree to which an issue is relevant or significant to an organization, taking into account both the impact of the issue and the stakeholder concern or interest in the issue. The handbook provides guidance on how to identify and prioritize ESG issues based on their materiality, and how to report on these issues effectively. The handbook covers several key areas, including the business case for materiality, how to assess materiality, how to determine stakeholder relevance and engagement, and how to report on material ESG issues. The handbook provides case studies and practical examples to illustrate these concepts and guide companies through the reporting process. The aim of the handbook is to help companies in Hong Kong improve their ESG reporting and ensure that their reporting is relevant, meaningful, and transparent to stakeholders. The handbook is designed for companies of all sizes and sectors, and can be used as a reference guide for those looking to improve their ESG reporting practices.', 'Hong Kong', 'climate', 'in_force', '2014-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_62', ARRAY['hong kong', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d578afd9-5771-517b-9926-46c8977f11d0', 'Hong Kong Air Pollution Control Bill', 'Air Pollution Control Bill', 'This bill amends the Air Pollution Control Ordinance to set out air quality objectives in the Ordinance; to provide for the review of those objectives with a view to promoting the conservation and best use of air in the public interest and to provide for related matters.', 'This bill amends the Air Pollution Control Ordinance to set out air quality objectives in the Ordinance; to provide for the review of those objectives with a view to promoting the conservation and best use of air in the public interest and to provide for related matters.', 'This bill amends the Air Pollution Control Ordinance to set out air quality objectives in the Ordinance; to provide for the review of those objectives with a view to promoting the conservation and best use of air in the public interest and to provide for related matters.', 'Hong Kong', 'climate', 'in_force', '2013-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_20', ARRAY['other sustainability policy', 'hong kong', 'regulations', 'sdg11', 'mandatory', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('842804bc-ab44-5be5-b248-dfaa2b03fcb6', 'Hong Kong Buildings Energy Efficiency Ordinance', 'Buildings Energy Efficiency Ordinance', 'The Buildings Energy Efficiency Ordinance (Cap. 610) is a legislative framework enacted in Hong Kong to promote energy efficiency in buildings. The ordinance requires building developers, owners, and tenants to comply with minimum energy efficiency standards and adopt sustainable building practices. It mandates the issuance of energy audit reports, energy efficiency certifications, and compliance with codes of practice for various building services installations, including lighting, air conditioning, and elevators.', 'The Buildings Energy Efficiency Ordinance (Cap. 610) is a legislative framework enacted in Hong Kong to promote energy efficiency in buildings. The ordinance requires building developers, owners, and tenants to comply with minimum energy efficiency standards and adopt sustainable building practices. It mandates the issuance of energy audit reports, energy efficiency certifications, and compliance with codes of practice for various building services installations, including lighting, air conditioning, and elevators.', 'The Buildings Energy Efficiency Ordinance (Cap. 610) is a legislative framework enacted in Hong Kong to promote energy efficiency in buildings. The ordinance requires building developers, owners, and tenants to comply with minimum energy efficiency standards and adopt sustainable building practices. It mandates the issuance of energy audit reports, energy efficiency certifications, and compliance with codes of practice for various building services installations, including lighting, air conditioning, and elevators.', 'Hong Kong', 'climate', 'in_force', '2012-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_2', ARRAY['hong kong', 'regulations', 'sdg7', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
