INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c7572c27-11ce-5a85-b9d8-5ea2250070e7', 'Hong Kong Corporate Governance Code and Corporate Governance Report', 'Corporate Governance Code and Corporate Governance Report 2007', 'This Code sets out the principles of good corporate governance, and two levels of recommendations: (a) code provisions; and (b) recommended best practice.', 'This Code sets out the principles of good corporate governance, and two levels of recommendations: (a) code provisions; and (b) recommended best practice.', 'This Code sets out the principles of good corporate governance, and two levels of recommendations: (a) code provisions; and (b) recommended best practice.', 'Hong Kong', 'climate', 'in_force', '2007-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_5', ARRAY['other sustainability policy', 'hong kong', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('54f3634f-53ec-5aee-8f37-af96427615d1', 'Hong Kong Guidance Notes on Construction Design and Management', 'Guidance Notes on Construction Design and Management', 'The main objective of this guidance is to achieve: i) Identification of potential health and safety hazards, and cost-effective mitigation measures at early stage of a project and continue throughout project delivery; nii) Early involvement and effective co-operation of all stakeholders through timely provision of relevant and necessary information; and iii) Clear demarcation of the roles and responsibilities of the parties responsible for coordinating and providing relevant project data on risks at all stages of a project.', 'The main objective of this guidance is to achieve: i) Identification of potential health and safety hazards, and cost-effective mitigation measures at early stage of a project and continue throughout project delivery; nii) Early involvement and effective co-operation of all stakeholders through timely provision of relevant and necessary information; and iii) Clear demarcation of the roles and responsibilities of the parties responsible for coordinating and providing relevant project data on risks at all stages of a project.', 'The main objective of this guidance is to achieve: i) Identification of potential health and safety hazards, and cost-effective mitigation measures at early stage of a project and continue throughout project delivery; nii) Early involvement and effective co-operation of all stakeholders through timely provision of relevant and necessary information; and iii) Clear demarcation of the roles and responsibilities of the parties responsible for coordinating and providing relevant project data on risks at all stages of a project.', 'Hong Kong', 'climate', 'in_force', '2006-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_36', ARRAY['guidance_frameworks', 'other sustainability policy', 'hong kong', 'sdg11', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8ee9f485-0ebf-5645-9dd4-27aab3bb5fea', 'Hong Kong Conclusions on Exposure of Draft Code on', 'Conclusions on Exposure of Draft Code on Corporate Governance Practices and Corporate Governance Report', 'This report summarises the main comments raised in response to the Exposure Paper and sets out the final conclusions of the Exchange.', 'This report summarises the main comments raised in response to the Exposure Paper and sets out the final conclusions of the Exchange.', 'This report summarises the main comments raised in response to the Exposure Paper and sets out the final conclusions of the Exchange.', 'Hong Kong', 'climate', 'in_force', '2004-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_12', ARRAY['other sustainability policy', 'hong kong', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
