INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b1a52bfd-7dbd-5de3-9d5f-563347979dae', 'Hong Kong Corporate Governance Disclosure in Annual Reports', 'Corporate Governance Disclosure in Annual Reports 2001', 'The aim of this Guide is to contribute towards the promotion of high standards of corporate governance disclosure in the annual reports of Hong Kong companies with particular reference to companies listed on the main board of the SEHK and the GEM, unlisted public companies, public corporations and large private companies.', 'The aim of this Guide is to contribute towards the promotion of high standards of corporate governance disclosure in the annual reports of Hong Kong companies with particular reference to companies listed on the main board of the SEHK and the GEM, unlisted public companies, public corporations and large private companies.', 'The aim of this Guide is to contribute towards the promotion of high standards of corporate governance disclosure in the annual reports of Hong Kong companies with particular reference to companies listed on the main board of the SEHK and the GEM, unlisted public companies, public corporations and large private companies.', 'Hong Kong', 'climate', 'in_force', '2001-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_11', ARRAY['hong kong', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a21831ad-0a7c-5948-a0e6-e473aeb586cc', 'Hong Kong Model Code for Securities Transactions by Directors', 'Model Code for Securities Transactions by Directors of Listed Companies: Basic Principles', 'This model code (both the basic principles and the rules) is seen by the Exchange as providing guidelines rather than rigid rules. It sets a minimum standard of good practice against which issuers should measure their own general code. In principle, a director should seek to secure that all dealings in which he is or is deemed to be interested be conducted in accordance with the model code.', 'This model code (both the basic principles and the rules) is seen by the Exchange as providing guidelines rather than rigid rules. It sets a minimum standard of good practice against which issuers should measure their own general code. In principle, a director should seek to secure that all dealings in which he is or is deemed to be interested be conducted in accordance with the model code.', 'This model code (both the basic principles and the rules) is seen by the Exchange as providing guidelines rather than rigid rules. It sets a minimum standard of good practice against which issuers should measure their own general code. In principle, a director should seek to secure that all dealings in which he is or is deemed to be interested be conducted in accordance with the model code.', 'Hong Kong', 'governance', 'in_force', '2001-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_13', ARRAY['voluntary', 'hong kong', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b3429e30-7d87-5dba-94aa-178923695c43', 'Hong Kong Code of Best Practice', 'Code of Best Practice, 1999', 'The following guidelines are intended to form the skeleton of a code of best practice to which listed issuers should aim. The following items are not intended to be rules which are to be rigidly adhered to. All issuers are encouraged to devise their own codes of practice in the interests not only of their independent non- executive directors, but of the board of directors as a whole.', 'The following guidelines are intended to form the skeleton of a code of best practice to which listed issuers should aim. The following items are not intended to be rules which are to be rigidly adhered to. All issuers are encouraged to devise their own codes of practice in the interests not only of their independent non- executive directors, but of the board of directors as a whole.', 'The following guidelines are intended to form the skeleton of a code of best practice to which listed issuers should aim. The following items are not intended to be rules which are to be rigidly adhered to. All issuers are encouraged to devise their own codes of practice in the interests not only of their independent non- executive directors, but of the board of directors as a whole.', 'Hong Kong', 'climate', 'in_force', '1999-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_9', ARRAY['sdg4', 'other sustainability policy', 'hong kong', 'regulations', 'sdg16', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('63987df0-34ef-52f2-b25f-8b0a46b820bc', 'Hungary Act C of 2000 about accounting', 'Act C of 2000 about accounting', 'The Act C of 2000 on accounting in Hungary, effective from November 20 to December 31, 2025, establishes accounting rules aligned with EU directives and international standards. It mandates reporting obligations, sustainability reporting, principles for bookkeeping, and requirements for disclosure and auditing for all economic participants.', 'The Act C of 2000 on accounting in Hungary, effective from November 20 to December 31, 2025, establishes accounting rules aligned with EU directives and international standards. It mandates reporting obligations, sustainability reporting, principles for bookkeeping, and requirements for disclosure and auditing for all economic participants.', 'The Act C of 2000 on accounting in Hungary, effective from November 20 to December 31, 2025, establishes accounting rules aligned with EU directives and international standards. It mandates reporting obligations, sustainability reporting, principles for bookkeeping, and requirements for disclosure and auditing for all economic participants.', 'Hungary', 'climate', 'in_force', '2025-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_20', ARRAY['sdg13', 'regulations', 'mandatory', 'hungary', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b1ac0f9a-809c-56dc-b9a1-0e6b5a2bfdf8', 'Hungary Act LIV of 2025 on certain tax obligations', 'Act LIV of 2025 on certain tax obligations and amendments to certain tax laws', 'The Act LIV of 2025 establishes new tax obligations and amends existing tax laws in Hungary, aimed at maintaining a competitive tax system. It introduces special taxes for financial institutions, requiring them to self-assess, declare, and pay these taxes for the 2025 and 2026 tax years based on their financial results from the previous years. The law applies specifically to credit institutions and financial enterprises, mandating compliance with these new tax regulations. The provisions are mandatory and will be in effect from February 2, 2026, to August 31, 2026.', 'The Act LIV of 2025 establishes new tax obligations and amends existing tax laws in Hungary, aimed at maintaining a competitive tax system. It introduces special taxes for financial institutions, requiring them to self-assess, declare, and pay these taxes for the 2025 and 2026 tax years based on their financial results from the previous years. The law applies specifically to credit institutions and financial enterprises, mandating compliance with these new tax regulations. The provisions are mandatory and will be in effect from February 2, 2026, to August 31, 2026.', 'The Act LIV of 2025 establishes new tax obligations and amends existing tax laws in Hungary, aimed at maintaining a competitive tax system. It introduces special taxes for financial institutions, requiring them to self-assess, declare, and pay these taxes for the 2025 and 2026 tax years based on their financial results from the previous years. The law applies specifically to credit institutions and financial enterprises, mandating compliance with these new tax regulations. The provisions are mandatory and will be in effect from February 2, 2026, to August 31, 2026.', 'Hungary', 'governance', 'in_force', '2025-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_23', ARRAY['regulations', 'mandatory', 'hungary', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('49c2a3f2-3f8d-5998-ab77-aa06f0a13cf7', 'Hungary rules of corporate social responsibility and other related', 'On the amendment of the rules of corporate social responsibility and other related laws, which take into account environmental, social and social aspects to encourage sustainable financing and uniform corporate responsibility 2023', 'In 2023, Hungary passed a law requiring companies to report on their sustainability performance. The law also establishes a framework for sustainable finance, including green bonds and sustainability-linked loans.', 'In 2023, Hungary passed a law requiring companies to report on their sustainability performance. The law also establishes a framework for sustainable finance, including green bonds and sustainability-linked loans.', 'In 2023, Hungary passed a law requiring companies to report on their sustainability performance. The law also establishes a framework for sustainable finance, including green bonds and sustainability-linked loans.', 'Hungary', 'climate', 'in_force', '2023-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_19', ARRAY['sdg4', 'regulations', 'mandatory', 'hungary', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7309dfa8-772b-587d-9028-58c547457d6b', 'Hungary Act CVIII of 2023 on Sustainable Finance', 'Act CVIII of 2023 on Sustainable Finance and Unified Corporate Responsibility', 'The Act CVIII of 2023 on Sustainable Finance and Unified Corporate Responsibility in Hungary aims to promote sustainable finance and corporate responsibility by requiring large undertakings to disclose ESG information. It targets entities meeting specific financial thresholds, ESG certifiers, consultants, software producers, and training institutions, emphasizing transparency and materiality in ESG reporting.', 'The Act CVIII of 2023 on Sustainable Finance and Unified Corporate Responsibility in Hungary aims to promote sustainable finance and corporate responsibility by requiring large undertakings to disclose ESG information. It targets entities meeting specific financial thresholds, ESG certifiers, consultants, software producers, and training institutions, emphasizing transparency and materiality in ESG reporting.', 'The Act CVIII of 2023 on Sustainable Finance and Unified Corporate Responsibility in Hungary aims to promote sustainable finance and corporate responsibility by requiring large undertakings to disclose ESG information. It targets entities meeting specific financial thresholds, ESG certifiers, consultants, software producers, and training institutions, emphasizing transparency and materiality in ESG reporting.', 'Hungary', 'climate', 'in_force', '2023-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_22', ARRAY['sdg4', 'regulations', 'mandatory', 'hungary', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('29564455-91df-580d-9e97-b6bc09d81325', 'Hungary Act XLV of 2022 on the Modification', 'Act XLV of 2022 on the Modification of Certain Tax Related Laws', 'The Act XLV of 2022 in Hungary modifies certain tax laws related to income tax. It introduces changes in personal income tax, entrepreneurial tax options, and investment contract regulations. The policy targets individuals, entrepreneurs, and organizations involved in tax reporting and compliance.', 'The Act XLV of 2022 in Hungary modifies certain tax laws related to income tax. It introduces changes in personal income tax, entrepreneurial tax options, and investment contract regulations. The policy targets individuals, entrepreneurs, and organizations involved in tax reporting and compliance.', 'The Act XLV of 2022 in Hungary modifies certain tax laws related to income tax. It introduces changes in personal income tax, entrepreneurial tax options, and investment contract regulations. The policy targets individuals, entrepreneurs, and organizations involved in tax reporting and compliance.', 'Hungary', 'climate', 'in_force', '2022-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_21', ARRAY['mandatory', 'hungary', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
