INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0562998f-4dc2-579d-9562-177e28d3e4da', 'Hungary 2017 LXXVL law', '2017 LXXVL law', 'Organisations receiving funding from abroad in excess of the limit determined in the legislation (7.2 million forints) must report the fact and source of the funding to the current court records system and state on their website(s) and publications that the Act classifies them as foreign-funded organisations.', 'Organisations receiving funding from abroad in excess of the limit determined in the legislation (7.2 million forints) must report the fact and source of the funding to the current court records system and state on their website(s) and publications that the Act classifies them as foreign-funded organisations.', 'Organisations receiving funding from abroad in excess of the limit determined in the legislation (7.2 million forints) must report the fact and source of the funding to the current court records system and state on their website(s) and publications that the Act classifies them as foreign-funded organisations.', 'Hungary', 'climate', 'in_force', '2017-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_6', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'hungary', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
